import sqlite3,json
from pathlib import Path
p=Path('.local/hermes-lab/home/profiles/slack-t0c6j1xcde0-u0c6m6dmwaw/state.db')
c=sqlite3.connect('file:'+str(p)+'?mode=ro',uri=True);c.row_factory=sqlite3.Row
rows=c.execute('select distinct s.id,s.started_at,s.thread_id from sessions s join messages m on m.session_id=s.id where s.thread_id=? or m.platform_message_id=?',('1791578793.201099','1791578793.201099')).fetchall()
print('sessions',[dict(r) for r in rows])
for r in rows:
 for m in c.execute('select id,role,tool_name,content,tool_calls,timestamp from messages where session_id=? order by id',(r['id'],)):
  if m['role']=='tool' and m['tool_name'] and m['tool_name'].startswith('clanker_'):
   try:d=json.loads(m['content'])
   except ValueError:d={'text':m['content'][:600]}
   # Vault inventory and private URLs are unnecessary for the payment blocker.
   if m['tool_name']=='clanker_vault_list':continue
   if isinstance(d,dict):
    d={k:v for k,v in d.items() if k not in {'items','collection_url','url','cdp_url'}}
   print(json.dumps({'id':m['id'],'tool':m['tool_name'],'result':d,'timestamp':m['timestamp']}))
  if m['role']=='assistant' and m['tool_calls']:
   calls=json.loads(m['tool_calls'])
   for call in calls:
    if 'payment' in call.get('function',{}).get('name',''):print(json.dumps({'id':m['id'],'tool_call':call}))
v=sqlite3.connect('file:.local/hermes-lab/home/.clanker-vault/requests.sqlite?mode=ro',uri=True);v.row_factory=sqlite3.Row
q="SELECT r.id,r.created,r.expires,r.status,r.source,p.state,p.approved,p.submitted FROM requests r JOIN kernel_purchases p ON p.request_id=r.id WHERE r.team=? AND r.owner=? ORDER BY r.created"
for r in v.execute(q,('T0C6J1XCDE0','U0C6M6DMWAW')):
 d=dict(r);s=json.loads(d.pop('source'));d['source_thread']=s.get('thread_id');print('purchase',d)
PY

